// Simple HTML parsing without external dependencies
const html = items[0].json.body;

if (!html || html.includes('Sign In') || html.includes('Challenge')) {
  return [{ json: { error: 'LinkedIn authentication required or blocked' } }];
}

const results = [];

// Extract names using regex patterns
const namePattern = /<span[^>]*entity-result__title-text[^>]*>.*?<a[^>]*>.*?<span[^>]*aria-hidden="true"[^>]*>([^<]+)<\/span>/g;
let nameMatch;
const names = [];
while ((nameMatch = namePattern.exec(html)) !== null) {
  const name = nameMatch[1].trim();
  if (name && !name.includes('View ') && name.length > 1) {
    names.push(name);
  }
}

// Extract job titles
const titlePattern = /<div[^>]*entity-result__primary-subtitle[^>]*>([^<]+)</g;
let titleMatch;
const titles = [];
while ((titleMatch = titlePattern.exec(html)) !== null) {
  titles.push(titleMatch[1].trim());
}

// Extract companies
const companyPattern = /<div[^>]*entity-result__secondary-subtitle[^>]*>([^<]+)</g;
let companyMatch;
const companies = [];
while ((companyMatch = companyPattern.exec(html)) !== null) {
  companies.push(companyMatch[1].trim());
}

// Extract profile URLs
const urlPattern = /<a[^>]*app-aware-link[^>]*href="([^"]+)"/g;
let urlMatch;
const urls = [];
while ((urlMatch = urlPattern.exec(html)) !== null) {
  let url = urlMatch[1];
  if (url.includes('/in/')) {
    // Clean URL
    if (url.startsWith('/')) {
      url = 'https://www.linkedin.com' + url;
    }
    url = url.split('?')[0]; // Remove tracking
    urls.push(url);
  }
}

// Fallback: try simpler patterns if main ones don't work
if (names.length === 0) {
  const fallbackNamePattern = /aria-label="View ([^"]+)'s profile"/g;
  let fallbackMatch;
  while ((fallbackMatch = fallbackNamePattern.exec(html)) !== null) {
    names.push(fallbackMatch[1].trim());
  }
}

// Combine all extracted data
const maxItems = Math.max(names.length, titles.length, companies.length, urls.length);

for (let i = 0; i < maxItems; i++) {
  const name = names[i] || 'N/A';
  const title = titles[i] || 'N/A';
  const company = companies[i] || 'N/A';
  const profileUrl = urls[i] || 'N/A';

  // Only add if we have at least a name
  if (name !== 'N/A' && name.length > 1) {
    results.push({
      json: {
        Name: name,
        Title: title,
        Company: company,
        LinkedIn_URL: profileUrl,
        Status: 'New',
        Scraped_Date: new Date().toISOString().split('T')[0], // Just date
        Source: 'LinkedIn Search'
      }
    });
  }
}

if (results.length === 0) {
  return [{ json: { error: 'No profiles found. LinkedIn may have changed structure.' } }];
}

console.log(`Found ${results.length} LinkedIn profiles`);
return results;

// Simple error logging
const errorMsg = items[0].json.error || 'Unknown error';
console.error('Scraping failed:', errorMsg);

return [{
  json: {
    Name: 'ERROR',
    Title: errorMsg,
    Company: 'N/A',
    LinkedIn_URL: 'N/A',
    Status: 'Error',
    Scraped_Date: new Date().toISOString().split('T')[0],
    Source: 'Error Log'
  }
}];
